rows.vgi.example_queries:
[
  {
    "description": "Read a header/detail/trailer flat file into a UNION column and project the detail rows' sku and qty.",
    "sql": "SELECT union_extract(record, 'D').sku AS sku, union_extract(record, 'D').qty AS qty FROM fixed.main.read_multi('data/multi.dat', '{\"discriminator\":{\"offset\":0,\"width\":1},\"records\":{\"H\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"co\",\"type\":\"str\",\"width\":20}],\"D\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"sku\",\"type\":\"str\",\"width\":10},{\"name\":\"qty\",\"type\":\"int\",\"digits\":5}],\"T\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"cnt\",\"type\":\"int\",\"digits\":6}]}}') WHERE union_tag(record) = 'D' ORDER BY sku"
  },
  {
    "description": "Count records of each type in a heterogeneous multi-record file.",
    "sql": "SELECT union_tag(record) AS record_type, count(*) AS n FROM fixed.main.read_multi('data/multi.dat', '{\"discriminator\":{\"offset\":0,\"width\":1},\"records\":{\"H\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"co\",\"type\":\"str\",\"width\":20}],\"D\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"sku\",\"type\":\"str\",\"width\":10},{\"name\":\"qty\",\"type\":\"int\",\"digits\":5}],\"T\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"cnt\",\"type\":\"int\",\"digits\":6}]}}') GROUP BY record_type ORDER BY record_type"
  },
  {
    "description": "Extract only the detail (D) records of a header/detail/trailer file with read_multi and write them to a flat sku/qty fixed-width file with write_fixed, dropping the header and trailer; returns 2 rows and 32 bytes.",
    "sql": "SELECT rows_written, bytes_written FROM fixed.main.write_fixed((SELECT d.sku, d.qty FROM (SELECT union_extract(record, 'D') AS d FROM fixed.main.read_multi('data/multi.dat', '{\"discriminator\":{\"offset\":0,\"width\":1},\"records\":{\"H\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"co\",\"type\":\"str\",\"width\":20}],\"D\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"sku\",\"type\":\"str\",\"width\":10},{\"name\":\"qty\",\"type\":\"int\",\"digits\":5}],\"T\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"cnt\",\"type\":\"int\",\"digits\":6}]}}') WHERE union_tag(record) = 'D')), 'data/_example_details.dat', 'sku:A10 qty:9(5)')"
  },
  {
    "description": "Reconcile a header/detail/trailer batch: report the header's company, the number of detail records and their total qty, the trailer's declared record count, and whether the detail count matches it (ACME CORP, 2 details, qty 49, trailer 2, balanced).",
    "sql": "WITH r AS (SELECT record FROM fixed.main.read_multi('data/multi.dat', '{\"discriminator\":{\"offset\":0,\"width\":1},\"records\":{\"H\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"co\",\"type\":\"str\",\"width\":20}],\"D\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"sku\",\"type\":\"str\",\"width\":10},{\"name\":\"qty\",\"type\":\"int\",\"digits\":5}],\"T\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"cnt\",\"type\":\"int\",\"digits\":6}]}}')) SELECT max(union_extract(record, 'H').co) AS company, count(*) FILTER (WHERE union_tag(record) = 'D') AS detail_records, sum(union_extract(record, 'D').qty) AS total_qty, max(union_extract(record, 'T').cnt) AS trailer_count, count(*) FILTER (WHERE union_tag(record) = 'D') = max(union_extract(record, 'T').cnt) AS balanced FROM r"
  }
]

[
  {
    "description": "Round-trip a heterogeneous flat file: read it into a UNION column and write it back out to a new multi-record file, reporting the counts.",
    "sql": "SELECT rows_written, bytes_written FROM fixed.main.write_multi((FROM fixed.main.read_multi('data/multi.dat', '{\"discriminator\":{\"offset\":0,\"width\":1},\"records\":{\"H\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"co\",\"type\":\"str\",\"width\":20}],\"D\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"sku\",\"type\":\"str\",\"width\":10},{\"name\":\"qty\",\"type\":\"int\",\"digits\":5}],\"T\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"cnt\",\"type\":\"int\",\"digits\":6}]}}')), 'data/_example_multi_out.dat', '{\"discriminator\":{\"offset\":0,\"width\":1},\"records\":{\"H\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"co\",\"type\":\"str\",\"width\":20}],\"D\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"sku\",\"type\":\"str\",\"width\":10},{\"name\":\"qty\",\"type\":\"int\",\"digits\":5}],\"T\":[{\"type\":\"filler\",\"width\":1},{\"name\":\"cnt\",\"type\":\"int\",\"digits\":6}]}}')"
  }
]

