  {"name": "bytes_written", "type": "BIGINT", "description": "Total number of bytes written to the file, including record framing and any compression."}
]

rows.vgi.example_queries:
[
  {
    "description": "Profile a newline-delimited fixed-width feed of 7-digit ids: count the rows and report the id range.",
    "sql": "SELECT count(*) AS records, min(id) AS min_id, max(id) AS max_id FROM fixed.main.read_fixed('data/large.dat', 'id:9(7)')"
  },
  {
    "description": "Glob several account files (10-char name, 5-digit qty) and total the quantity across every record.",
    "sql": "SELECT sum(qty) AS total_qty FROM fixed.main.read_fixed('data/acct*.dat', 'name:A10 qty:9(5)')"
  }
]

[
  {
    "description": "Resolve a header/detail multi-record spec and show each record type's fields with their DuckDB types and byte offsets.",
    "sql": "SELECT record_type, path, sql_type, byte_offset FROM fixed.main.describe_multi('{\"discriminator\":{\"offset\":0,\"width\":1},\"records\":{\"H\":[{\"name\":\"co\",\"type\":\"str\",\"width\":20}],\"D\":[{\"name\":\"sku\",\"type\":\"str\",\"width\":10},{\"name\":\"qty\",\"type\":\"int\",\"digits\":5}]}}') ORDER BY record_type, byte_offset"
  },
  {
    "description": "Count how many fields each record type declares in a multi-record layout.",
    "sql": "SELECT record_type, count(*) AS field_count FROM fixed.main.describe_multi('{\"discriminator\":{\"offset\":0,\"width\":1},\"records\":{\"H\":[{\"name\":\"co\",\"type\":\"str\",\"width\":20}],\"D\":[{\"name\":\"sku\",\"type\":\"str\",\"width\":10},{\"name\":\"qty\",\"type\":\"int\",\"digits\":5}]}}') GROUP BY record_type ORDER BY record_type"
  }
]

[
  {
    "description": "Introspect a two-field template layout: show each field's DuckDB type, byte offset, and width.",
    "sql": "SELECT path, sql_type, byte_offset, width FROM fixed.main.describe_fixed('name:A10 qty:9(5)') ORDER BY byte_offset"
  },
  {
    "description": "Resolve a COBOL copybook (forcing the copybook format) and list only the repeating OCCURS fields.",
    "sql": "SELECT path, sql_type, occurs FROM fixed.main.describe_fixed('01 REC. 05 SKU PIC X(8). 05 QTY PIC 9(3) OCCURS 4.', format => 'copybook') WHERE occurs IS NOT NULL"
  }
]

[
  {
    "description": "Write two accounts to a newline-framed fixed-width file (10-char name, 5-digit quantity) and report how much was written.",
    "sql": "SELECT rows_written, bytes_written FROM fixed.main.write_fixed((FROM (VALUES ('ALICE', 5), ('BOB', 999)) AS v(name, qty)), 'data/_example_write.dat', 'name:A10 qty:9(5)')"
  },
  {
    "description": "Write back-to-back fixed-length records (no newline) by forcing the framing named argument, returning just the record count.",
    "sql": "SELECT rows_written FROM fixed.main.write_fixed((FROM (VALUES ('ALICE', 5), ('BOB', 999)) AS v(name, qty)), 'data/_example_write.dat', 'name:A10 qty:9(5)', framing => 'fixed')"
  },
  {
    "description": "Convert an ASCII newline feed (10-char name, 5-digit qty) into a fixed-length EBCDIC mainframe file with a packed-decimal COMP-3 quantity by piping read_fixed into write_fixed; returns 3 rows and 39 bytes (13-byte records, no separators).",
    "sql": "SELECT rows_written, bytes_written FROM fixed.main.write_fixed((FROM fixed.main.read_fixed('data/accounts.dat', 'name:A10 qty:9(5)')), 'data/_example_ebcdic.dat', '01 ACCT. 05 NAME PIC X(10). 05 QTY PIC S9(5) COMP-3.', encoding => 'ebcdic', framing => 'fixed')"
  }
]

